select 'dist_L', string_agg(b||':'||n, '  ' order by b) from (select case when r<0.75 then '1<-25%' when r<0.95 then '2 -25..-5' when r<=1.05 then '3 +-5' when r<=1.25 then '4 +5..25' else '5 >+25%' end b, count(*) n from (select l_cop/cop r from sim.cmp where cop>0) y group by 1) z;
select 'dist_E', string_agg(b||':'||n, '  ' order by b) from (select case when r<0.75 then '1<-25%' when r<0.95 then '2 -25..-5' when r<=1.05 then '3 +-5' when r<=1.25 then '4 +5..25' else '5 >+25%' end b, count(*) n from (select e_cop/cop r from sim.cmp where cop>0) y group by 1) z;
select 'median L/E', round(percentile_cont(0.5) within group (order by l_cop/cop)::numeric,3), round(percentile_cont(0.5) within group (order by e_cop/cop)::numeric,3) from sim.cmp where cop>0;
select 'neg old/E/L/B', count(*) filter (where ikm<0 or okm<0), count(*) filter (where ikm-(e_cop-cop)<0 or okm-(e_cop-cop)<0), count(*) filter (where ikm-(l_cop-cop)<0 or okm-(l_cop-cop)<0), count(*) filter (where ikm-(b_cop-cop)<0 or okm-(b_cop-cop)<0) from sim.cmp;
select 'keys', string_agg(sku_id||'='||round(l_cop,2), ' ' order by sku_id) from sim.cmp where sku_id in (865,878,1769,1770,1792,879,988,1797,876,637,111);
